import java.io.BufferedReader;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;

public class Main {
    static int countLines(String name) throws IOException {
        int n = 0;
        try (BufferedReader r = new BufferedReader(new FileReader(name))) {
            String hang = r.readLine();
            while (hang != null) {
                n++;
                hang = r.readLine();
            }
        }
        return n;
    }

    public static void main(String[] args) throws IOException {
        try (FileWriter w = new FileWriter("{name}")) {
            w.write("{old}\n");
        }
        System.out.println("今天之前：" + countLines("{name}") + " 条");
        try (FileWriter w = new FileWriter("{name}", true)) {
            w.write("{f1}\n");
            w.write("{f2}\n");
        }
        int n = 0;
        try (BufferedReader r = new BufferedReader(new FileReader("{name}"))) {
            String hang = r.readLine();
            while (hang != null) {
                n++;
                System.out.println("档案里有：" + hang);
                hang = r.readLine();
            }
        }
        System.out.println("现在一共 " + n + " 条");
    }
}
